    }
    private static int[] distances(Maze m,int start){int[] ds=new int[m.size()*m.size()];Arrays.fill(ds,-1);ds[start]=0;Deque<Integer> q=new ArrayDeque<>();q.add(start);while(!q.isEmpty()){int r=q.remove();for(int d=0;d<4;d++){int n=neighbor(r,d,m.size());if(n>=0&&!wall(m,r,d)&&ds[n]<0){ds[n]=ds[r]+1;q.add(n);}}}return ds;}
    /** Only admission/tests may call this witness. Players receive observations, never this value. */
    public static List<String> witness(GameState g){
        int[] ds=distances(g.maze(),g.maze().exitRoom());if(ds[g.room()]<0)throw new IllegalStateException("unreachable exit");
